463→// Git runs a git command in the given directory and fails the test if it
464→// returns a non-zero exit code.
465→func Git(t *testing.T, dir string, args ...string) {
466→	t.Helper()
467→
468→	cmd := exec.Command("git", args...)
469→	if dir != "" {
470→		cmd.Dir = dir
471→	}
472→	cmd.Env = append(os.Environ(), "ENTIRE_TEST_TTY=0")
473→
474→	out, err := cmd.CombinedOutput()
475→	if err != nil {
476→		t.Fatalf("git %s failed: %v\n%s", strings.Join(args, " "), err, out)
477→	}
