480→// GitOutput runs a git command in the given directory, returns its trimmed
481→// stdout, and fails the test on error.
482→func GitOutput(t *testing.T, dir string, args ...string) string {
483→	t.Helper()
484→
485→	cmd := exec.Command("git", args...)
486→	if dir != "" {
487→		cmd.Dir = dir
