489→
490→	out, err := cmd.Output()
491→	if err != nil {
492→		var stderr string
493→		ee := &exec.ExitError{}
494→		if errors.As(err, &ee) {
495→			stderr = string(ee.Stderr)
496→		}
497→		t.Fatalf("git %s failed: %v\n%s", strings.Join(args, " "), err, stderr)
498→	}
