515→// CheckpointIDs lists all checkpoint IDs from the tree at the tip of the
516→// checkpoint branch. It parses the two-level directory structure
517→// ({prefix}/{suffix}/metadata.json) and returns the concatenated IDs.
518→func CheckpointIDs(t *testing.T, dir string) []string {
519→	t.Helper()
520→	out := gitOutputSafe(dir, "ls-tree", "-r", "--name-only", "entire/checkpoints/v1")
521→	if out == "" {
522→		return nil
523→	}
524→	seen := map[string]bool{}
525→	var ids []string
526→	for _, line := range strings.Split(strings.TrimSpace(out), "\n") {
527→		// Match {prefix}/{suffix}/metadata.json (top-level, not session-level)
528→		parts := strings.Split(line, "/")
529→		if len(parts) == 3 && parts[2] == "metadata.json" {
530→			id := parts[0] + parts[1]
531→			if !seen[id] {
532→				seen[id] = true
533→				ids = append(ids, id)
534→			}
535→		}
536→	}
537→	return ids
538→}
