257→// WaitForSessionIdle polls the session state files in .git/entire-sessions/
258→// until no session has phase "active", or fails the test after timeout.
259→// This handles the race where an agent's prompt pattern appears in the TUI
260→// before the turn-end hook has completed (transitioning ACTIVE → IDLE).
261→func WaitForSessionIdle(t *testing.T, dir string, timeout time.Duration) {
262→	t.Helper()
263→	stateDir := filepath.Join(dir, ".git", "entire-sessions")
264→	deadline := time.Now().Add(timeout)
265→	for time.Now().Before(deadline) {
266→		entries, err := os.ReadDir(stateDir)
267→		if err != nil {
268→			// Directory may not exist yet; keep polling
269→			time.Sleep(200 * time.Millisecond)
270→			continue
271→		}
272→		anyActive := false
273→		for _, entry := range entries {
274→			if entry.IsDir() || !strings.HasSuffix(entry.Name(), ".json") || strings.HasSuffix(entry.Name(), ".tmp") {
275→				continue
276→			}
277→			data, err := os.ReadFile(filepath.Join(stateDir, entry.Name()))
278→			if err != nil {
279→				continue
280→			}
281→			var state struct {
282→				Phase string `json:"phase"`
283→			}
284→			if err := json.Unmarshal(data, &state); err != nil {
285→				continue
286→			}
287→			if state.Phase == "active" {
288→				anyActive = true
289→				break
290→			}
291→		}
292→		if !anyActive {
293→			return
294→		}
295→		time.Sleep(200 * time.Millisecond)
296→	}
297→	t.Fatalf("session(s) did not transition to idle within %s", timeout)
298→}
