337→// ValidateCheckpointDeep performs comprehensive validation of checkpoint metadata
338→// on the checkpoint branch, including transcript JSONL validity, content hash
339→// verification, and prompt content checking.
340→func ValidateCheckpointDeep(t *testing.T, dir string, v DeepCheckpointValidation) {
341→	t.Helper()
342→
343→	// Basic metadata validation
344→	AssertCheckpointExists(t, dir, v.CheckpointID)
345→	AssertCheckpointMetadataComplete(t, dir, v.CheckpointID)
346→
347→	if v.Strategy != "" {
348→		meta := ReadCheckpointMetadata(t, dir, v.CheckpointID)
349→		assert.Equal(t, v.Strategy, meta.Strategy,
350→			"checkpoint %s: strategy mismatch", v.CheckpointID)
351→	}
352→
353→	if len(v.FilesTouched) > 0 {
354→		AssertCheckpointFilesTouched(t, dir, v.CheckpointID, v.FilesTouched)
355→	}
356→
357→	path := CheckpointPath(v.CheckpointID)
358→
359→	// Validate session metadata exists and has checkpoint_id
360→	sessionBlob := fmt.Sprintf("entire/checkpoints/v1:%s/0/metadata.json", path)
361→	sessionRaw := gitOutputSafe(dir, "show", sessionBlob)
362→	if assert.NotEmpty(t, sessionRaw, "session metadata should exist at %s", sessionBlob) {
363→		var sessionMeta map[string]any
364→		if assert.NoError(t, json.Unmarshal([]byte(sessionRaw), &sessionMeta)) {
365→			assert.Equal(t, v.CheckpointID, sessionMeta["checkpoint_id"],
366→				"session metadata checkpoint_id should match")
367→			assert.NotEmpty(t, sessionMeta["created_at"], "session metadata should have created_at")
368→		}
369→	}
370→
371→	// Validate transcript is valid JSONL
372→	transcriptBlob := fmt.Sprintf("entire/checkpoints/v1:%s/0/full.jsonl", path)
373→	transcriptRaw := gitOutputSafe(dir, "show", transcriptBlob)
374→	if assert.NotEmpty(t, transcriptRaw, "transcript should exist at %s", transcriptBlob) {
375→		lines := strings.Split(transcriptRaw, "\n")
376→		nonEmpty := 0
377→		for _, line := range lines {
378→			if strings.TrimSpace(line) != "" {
379→				nonEmpty++
380→			}
381→		}
382→		assert.Positive(t, nonEmpty, "transcript should have at least one line")
383→
384→		for _, expected := range v.ExpectedTranscriptContent {
385→			assert.Contains(t, transcriptRaw, expected,
386→				"transcript should contain %q", expected)
387→		}
388→
389→		// Validate content hash
390→		hashBlob := fmt.Sprintf("entire/checkpoints/v1:%s/0/content_hash.txt", path)
391→		hashRaw := gitOutputSafe(dir, "show", hashBlob)
392→		if hashRaw != "" {
393→			hash := sha256.Sum256([]byte(transcriptRaw))
394→			expectedHash := "sha256:" + hex.EncodeToString(hash[:])
395→			assert.Equal(t, expectedHash, strings.TrimSpace(hashRaw),
396→				"content hash should match transcript SHA-256")
397→		}
398→	}
399→
400→	// Validate prompt.txt if expected prompts specified
401→	if len(v.ExpectedPrompts) > 0 {
402→		promptBlob := fmt.Sprintf("entire/checkpoints/v1:%s/0/prompt.txt", path)
403→		promptRaw := gitOutputSafe(dir, "show", promptBlob)
404→		for _, expected := range v.ExpectedPrompts {
405→			assert.Contains(t, promptRaw, expected,
406→				"prompt.txt should contain %q", expected)
407→		}
408→	}
409→}
410→

  1→// Package vogon implements the Agent interface for a deterministic test agent
  2→// used as an E2E canary. It exercises the full checkpoint/hook lifecycle without
  3→// real API calls. Named after the Vogons from The Hitchhiker's Guide to the
  4→// Galaxy — bureaucratic, procedural, and deterministic to a fault.
  5→package vogon
  6→
  7→import (
  8→	"context"
  9→	"errors"
 10→	"fmt"
 11→	"os"
 12→	"path/filepath"
 13→
 14→	"github.com/entireio/cli/cmd/entire/cli/agent"
 15→	"github.com/entireio/cli/cmd/entire/cli/agent/types"
 16→)
 17→
 18→//nolint:gochecknoinits // Agent self-registration is the intended pattern
 19→func init() {
 20→	agent.Register(AgentNameVogon, NewAgent)
 21→}
 22→
 23→const (
 24→	// AgentNameVogon is the registry key for the vogon agent.
 25→	AgentNameVogon types.AgentName = "vogon"
 26→	// AgentTypeVogon is the type identifier stored in metadata.
 27→	AgentTypeVogon types.AgentType = "Vogon Agent"
 28→)
 29→
 30→// Agent implements agent.Agent and agent.HookSupport for E2E canary tests.
 31→type Agent struct{}
 32→
 33→// NewAgent creates a new vogon agent instance.
 34→func NewAgent() agent.Agent { return &Agent{} }
 35→
 36→func (v *Agent) Name() types.AgentName { return AgentNameVogon }
 37→func (v *Agent) Type() types.AgentType { return AgentTypeVogon }
 38→func (v *Agent) Description() string {
 39→	return "Vogon Agent - deterministic E2E canary (no API calls)"
 40→}
 41→func (v *Agent) IsPreview() bool         { return false }
 42→func (v *Agent) ProtectedDirs() []string { return []string{".vogon"} }
 43→
 44→// DetectPresence returns false — vogon agent is never auto-detected.
 45→func (v *Agent) DetectPresence(_ context.Context) (bool, error) { return false, nil }
 46→
 47→// IsTestOnly marks this agent as test-only, excluding it from `entire enable`.
 48→func (v *Agent) IsTestOnly() bool { return true }
 49→
 50→// --- Transcript Storage ---
 51→
 52→func (v *Agent) ReadTranscript(sessionRef string) ([]byte, error) {
 53→	data, err := os.ReadFile(sessionRef) //nolint:gosec // Path from hook input
 54→	if err != nil {
 55→		return nil, fmt.Errorf("read transcript: %w", err)
 56→	}
 57→	return data, nil
 58→}
 59→
 60→func (v *Agent) ChunkTranscript(_ context.Context, content []byte, maxSize int) ([][]byte, error) {
 61→	chunks, err := agent.ChunkJSONL(content, maxSize)
 62→	if err != nil {
 63→		return nil, fmt.Errorf("chunk transcript: %w", err)
 64→	}
 65→	return chunks, nil
 66→}
 67→
 68→func (v *Agent) ReassembleTranscript(chunks [][]byte) ([]byte, error) {
 69→	return agent.ReassembleJSONL(chunks), nil
 70→}
 71→
 72→// --- Legacy Session Methods ---
 73→
 74→func (v *Agent) GetSessionID(input *agent.HookInput) string { return input.SessionID }
 75→
 76→func (v *Agent) GetSessionDir(_ string) (string, error) {
 77→	if override := os.Getenv("ENTIRE_TEST_VOGON_PROJECT_DIR"); override != "" {
 78→		return override, nil
 79→	}
 80→	homeDir, err := os.UserHomeDir()
 81→	if err != nil {
 82→		return "", fmt.Errorf("get home dir: %w", err)
 83→	}
 84→	return filepath.Join(homeDir, ".vogon", "sessions"), nil
 85→}
 86→
 87→func (v *Agent) ResolveSessionFile(sessionDir, agentSessionID string) string {
 88→	return filepath.Join(sessionDir, agentSessionID+".jsonl")
 89→}
 90→
 91→func (v *Agent) ReadSession(input *agent.HookInput) (*agent.AgentSession, error) {
 92→	if input.SessionRef == "" {
 93→		return nil, errors.New("session reference (transcript path) is required")
 94→	}
 95→	data, err := os.ReadFile(input.SessionRef)
 96→	if err != nil {
 97→		if os.IsNotExist(err) {
 98→			// Transcript may not exist yet — return empty session
 99→			return &agent.AgentSession{
100→				SessionID:  input.SessionID,
101→				AgentName:  v.Name(),
102→				SessionRef: input.SessionRef,
103→			}, nil
104→		}
105→		return nil, fmt.Errorf("read transcript: %w", err)
106→	}
107→	return &agent.AgentSession{
108→		SessionID:  input.SessionID,
109→		AgentName:  v.Name(),
110→		SessionRef: input.SessionRef,
111→		NativeData: data,
112→	}, nil
113→}
114→
115→func (v *Agent) WriteSession(_ context.Context, session *agent.AgentSession) error {
116→	if session == nil {
117→		return errors.New("session is nil")
118→	}
119→	if session.SessionRef == "" {
120→		return errors.New("session reference is required")
121→	}
122→	if err := os.MkdirAll(filepath.Dir(session.SessionRef), 0o750); err != nil {
123→		return fmt.Errorf("create session dir: %w", err)
124→	}
125→	if err := os.WriteFile(session.SessionRef, session.NativeData, 0o600); err != nil {
126→		return fmt.Errorf("write session: %w", err)
127→	}
128→	return nil
129→}
130→
131→func (v *Agent) FormatResumeCommand(sessionID string) string {
132→	return "vogon --session-id " + sessionID
133→}
