445→func deleteFile(dir, path string) {
446→	abs := filepath.Join(dir, path)
447→	if err := os.Remove(abs); err != nil {
448→		fmt.Fprintf(os.Stderr, "remove %s: %v\n", abs, err)
449→	}
450→}
