func NewRepoWithCommit(t *testing.T) *TestEnv {
	t.Helper()
	env := NewRepoEnv(t)
	env.WriteFile(".gitignore", ".entire/\n")
	env.WriteFile("README.md", "# Test Repository")
	env.GitAdd(".gitignore")
	env.GitAdd("README.md")
	env.GitCommit("Initial commit")
